package org.retrobridge.galaxyservices.s2;
import android.app.*;import android.content.*;import android.net.wifi.*;import android.os.*;

final class DeviceLink {
 final LegacyService service;HotspotLink hotspot;WifiManager.WifiLock wifi,reconnectWifi;PowerManager.WakeLock reconnectWake;BroadcastReceiver receiver;Handler handler=new Handler();volatile boolean retry=true;
 DeviceLink(LegacyService s){service=s;}
 PendingIntent alarm(){return PendingIntent.getService(service,7,new Intent(service,LegacyService.class).putExtra("calendar",true),PendingIntent.FLAG_UPDATE_CURRENT);}
 PendingIntent retryAlarm(){return PendingIntent.getService(service,8,new Intent(service,LegacyService.class).putExtra("networkRetry",true),PendingIntent.FLAG_UPDATE_CURRENT);}
 void retryLater(){if(!service.stopping)((AlarmManager)service.getSystemService(Context.ALARM_SERVICE)).set(AlarmManager.ELAPSED_REALTIME_WAKEUP,SystemClock.elapsedRealtime()+60000,retryAlarm());}
 void start(){hotspot=new HotspotLink(service);
  WifiManager w=(WifiManager)service.getSystemService(Context.WIFI_SERVICE);wifi=w.createWifiLock(WifiManager.WIFI_MODE_FULL,"GalaxyServices:connection");wifi.acquire();
  reconnectWifi=w.createWifiLock(WifiManager.WIFI_MODE_FULL_HIGH_PERF,"GalaxyServices:rejoin");reconnectWifi.setReferenceCounted(false);
  reconnectWake=((PowerManager)service.getSystemService(Context.POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"GalaxyServices:rejoin");reconnectWake.setReferenceCounted(false);retryLater();
  if(!w.isWifiEnabled())w.setWifiEnabled(true);
  band(2);
  ((AlarmManager)service.getSystemService(Context.ALARM_SERVICE)).setInexactRepeating(AlarmManager.ELAPSED_REALTIME_WAKEUP,SystemClock.elapsedRealtime()+900000,900000,alarm());
  receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(i.getAction().equals(WifiManager.WIFI_STATE_CHANGED_ACTION)&&i.getIntExtra(WifiManager.EXTRA_WIFI_STATE,-1)==WifiManager.WIFI_STATE_ENABLED)band(2);if(i.getAction().equals(WifiManager.NETWORK_STATE_CHANGED_ACTION))handler.postDelayed(new Runnable(){public void run(){sync();if(service.camera!=null)service.camera.kick();}},5000);}};
  IntentFilter f=new IntentFilter(WifiManager.WIFI_STATE_CHANGED_ACTION);f.addAction(WifiManager.NETWORK_STATE_CHANGED_ACTION);service.registerReceiver(receiver,f);handler.postDelayed(new Runnable(){public void run(){sync();}},20000);
  handler.postDelayed(new Runnable(){public void run(){if(service.stopping)return;rejoin();if(retry)sync();handler.postDelayed(this,30000);}},30000);
 }
 void rejoin(){if(hotspot!=null)hotspot.kick();try{WifiManager w=(WifiManager)service.getSystemService(Context.WIFI_SERVICE);WifiInfo info=w.getConnectionInfo();if(!w.isWifiEnabled()||info.getNetworkId()>=0)return;SupplicantState state=info.getSupplicantState();if(state!=SupplicantState.DISCONNECTED&&state!=SupplicantState.INACTIVE&&state!=SupplicantState.SCANNING)return;String name=service.network;if(name==null)return;java.util.List<WifiConfiguration> saved=w.getConfiguredNetworks();if(saved==null)return;for(WifiConfiguration c:saved)if(("\""+name+"\"").equals(c.SSID)||name.equals(c.SSID)){if(!reconnectWake.isHeld())reconnectWake.acquire(20000);if(!reconnectWifi.isHeld()){reconnectWifi.acquire();handler.postDelayed(new Runnable(){public void run(){if(reconnectWifi.isHeld())reconnectWifi.release();}},15000);}w.enableNetwork(c.networkId,false);w.reconnect();w.startScan();return;}}catch(Exception ignored){}}
 void band(int value){try{WifiManager w=(WifiManager)service.getSystemService(Context.WIFI_SERVICE);SharedPreferences p=service.getSharedPreferences("settings",0);if(!p.contains("originalBand"))p.edit().putInt("originalBand",(Integer)w.getClass().getMethod("getFrequencyBand").invoke(w)).commit();if(((Integer)w.getClass().getMethod("getFrequencyBand").invoke(w))!=value)w.getClass().getMethod("setFrequencyBand",int.class,boolean.class).invoke(w,value,false);}catch(Exception ignored){}}
 void sync(){if(service.stopping||!service.getSharedPreferences("settings",0).getBoolean("enabled",true))return;new Thread(new Runnable(){public void run(){PowerManager.WakeLock wake=((PowerManager)service.getSystemService(Context.POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"GalaxyServices:calendar");wake.acquire(120000);try{service.setProxy(true);service.gateway();retry=!CalendarMirror.run(service);}catch(Exception e){retry=true;CalendarMirror.status(service,"Waiting for Pixel Wi-Fi");}finally{if(retry)retryLater();else ((AlarmManager)service.getSystemService(Context.ALARM_SERVICE)).cancel(retryAlarm());if(wake.isHeld())wake.release();}}},"calendar-sync").start();}
 void stop(){if(hotspot!=null)hotspot.close();handler.removeCallbacksAndMessages(null);((AlarmManager)service.getSystemService(Context.ALARM_SERVICE)).cancel(retryAlarm());if(reconnectWake!=null&&reconnectWake.isHeld())reconnectWake.release();if(reconnectWifi!=null&&reconnectWifi.isHeld())reconnectWifi.release();if(receiver!=null)service.unregisterReceiver(receiver);if(wifi!=null&&wifi.isHeld())wifi.release();if(!service.getSharedPreferences("settings",0).getBoolean("enabled",true)){((AlarmManager)service.getSystemService(Context.ALARM_SERVICE)).cancel(alarm());band(service.getSharedPreferences("settings",0).getInt("originalBand",0));}}
}
